    public static function getMenuGroups(): array
    {
        if (! auth()->check()) {
            return [];
        }

        $user = auth()->user();

        $permissionCodes = $user->roles()
            ->with('permissions')
            ->get()
            ->flatMap(fn($role) => $role->permissions)
            ->where('is_active', true)
            ->pluck('permission_code')
            ->unique()
            ->toArray();

        $parentMenus = Menu::with(['children' => function ($query) use ($permissionCodes) {
                $query->where(function ($q) use ($permissionCodes) {
                        $q->whereNull('permission_id')
                          ->orWhereHas('permissions', function ($qp) use ($permissionCodes) {
                              $qp->whereIn('permission_code', $permissionCodes);
                          });
                    })
                    ->where('is_active', true)
                    ->orderBy('sort_order');
            }])
            ->whereNull('parent_id')
            ->where('is_active', true)
            ->orderBy('sort_order')
            ->get()
            ->filter(fn($menu) => $menu->children->count() > 0);

        $items = $parentMenus->map(function ($menu) {
            $item = [
                'name' => $menu->menu_name,
                'icon' => $menu->icon ?? 'dashboard',
            ];

            if ($menu->children->count() > 0) {
                $item['subItems'] = $menu->children->map(fn($child) => [
                    'name' => $child->menu_name,
                    'path' => self::resolveRoutePath($child->route_name),
                ])->toArray();
            } else {
                $item['path'] = self::resolveRoutePath($menu->route_name);
            }

            return $item;
        })->toArray();

        return [
            ['title' => 'Menu', 'items' => $items],
        ];
    }

    public static function getAvailableIcons(): array
